def R1 (a ,b ,c , d ) :
    return ( S (a ,b ,c , d ) - S ( a +1 , b - 1 ,c , d ) - z * q ^( a + 1 ) * S ( a +2 ,b , c -1 , d ) )

def R2 (a ,b ,c , d ) :
    return ( S (a ,b ,c , d ) - S ( a ,b , c + 1 , d - 1 ) - q ^( c + 1 ) * S ( a -1 ,b , c +2 , d ) )

def R3 (a ,b ,c , d ) :
    return ( S (a ,b ,c , d ) - S ( a ,b ,c , d + 1 ) - q * S (a , b +1 ,c , d + 1 )
                + q * S (a , b + 1 ,c , d + 2 ) - q ^( c + d + 2 ) * S ( a -1 , b -1 , c +2 , d + 2 ) )

def R4 (a ,b ,c , d ) :
    return ( S (a ,b ,c , d ) - S ( a , b +1 , c , d ) - q * S (a , b +1 ,c , d + 1 )
                + q * S (a , b + 2 ,c , d + 1 ) - z * q ^( a + b + 2 ) * S ( a +2 , b +2 , c -1 , d - 1 ) )


